# Wildbound move database.
# cat: P physical, S special, X status. acc None = never misses. tgt: foe, foes, others, self, ally, side, foeside, field, any
# effect DSL (engine): semicolon-separated tokens, e.g. burn:10 ; stat:foe:def:-1:20 ; stat:self:spe:+1:100 ; recoil:33 ; drain:50
MOVES = []
def M(t, name, cat, pw, acc, pp, prio=0, tgt='foe', contact=False, flags='', eff='', desc='', res=''):
    MOVES.append(dict(type=t, name=name, cat=cat, power=pw, acc=acc, pp=pp, prio=prio, target=tgt,
                      contact=contact, flags=flags, effect=eff, desc=desc, resonance=res))

